import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# CUDA kernel source (inline)
# ----------------------------------------------------------------------
src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <typename scalar_t>
__global__ void avg_pool1d_fp16_kernel(
    const scalar_t* __restrict__ input,
    scalar_t* __restrict__ output,
    const int64_t batch,
    const int64_t channels,
    const int64_t input_len,
    const int64_t output_len,
    const int kernel_size,
    const int stride,
    const int padding)
{
    // One thread per output element (b, c, o)
    const int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int64_t total = batch * channels * output_len;
    if (idx >= total) return;

    const int64_t o = idx % output_len;
    const int64_t rc = idx / output_len;
    const int64_t c = rc % channels;
    const int64_t b = rc / channels;

    const int64_t in_start = static_cast<int64_t>(o) * stride - padding;
    float sum = 0.0f;
    int count = 0;

    // accumulate over kernel window
    #pragma unroll
    for (int k = 0; k < kernel_size; ++k) {
        int64_t pos = in_start + k;
        if (pos >= 0 && pos < input_len) {
            const int64_t in_idx = b * channels * input_len
                                 + c * input_len
                                 + pos;
            sum += static_cast<float>(input[in_idx]);
            ++count;
        }
    }
    // For average pooling PyTorch divides by kernel_size even if some
    // elements are out‑of‑bounds (they are treated as zero). Hence we
    // keep divisor = kernel_size.
    float avg = sum / static_cast<float>(kernel_size);
    const int64_t out_idx = b * channels * output_len
                          + c * output_len
                          + o;
    output[out_idx] = static_cast<scalar_t>(avg);
}

at::Tensor avg_pool1d_fp16(
    const at::Tensor& input,
    const int64_t kernel_size,
    const int64_t stride,
    const int64_t padding)
{
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.dtype() == at::kHalf, "input must be half precision");
    TORCH_CHECK(input.dim() == 3, "input must be 3‑D (B, C, L)");

    const int64_t batch   = input.size(0);
    const int64_t channels= input.size(1);
    const int64_t in_len  = input.size(2);

    const int64_t out_len = (in_len + 2 * padding - kernel_size) / stride + 1;
    TORCH_CHECK(out_len > 0, "output length must be positive");

    auto output = at::empty({batch, channels, out_len},
                            input.options());

    const int threads = 256;
    const int64_t total = batch * channels * out_len;
    const int blocks = (total + threads - 1) / threads;

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "avg_pool1d_fp16_kernel", ([&] {
        avg_pool1d_fp16_kernel<scalar_t><<<blocks, threads>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            batch,
            channels,
            in_len,
            out_len,
            static_cast<int>(kernel_size),
            static_cast<int>(stride),
            static_cast<int>(padding));
    }));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA kernel failed : ", cudaGetErrorString(err));
    }

    return output;
}

// ----------------------------------------------------------------------
// PyTorch binding
// ----------------------------------------------------------------------
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("avg_pool1d_fp16", &avg_pool1d_fp16,
          "1D average pooling (fp16) CUDA implementation");
}
'''

# ----------------------------------------------------------------------
# Compile the extension
# ----------------------------------------------------------------------
ext = load_inline(name='avg_pool1d_fp16_ext',
                  cpp_sources='',
                  cuda_sources=src,
                  functions=['avg_pool1d_fp16'],
                  verbose=False)

# ----------------------------------------------------------------------
# Model using the custom kernel
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model, but using a custom
    CUDA kernel for fp16 1‑D average pooling.
    """
    def __init__(self, kernel_size: int, stride: int = 1, padding: int = 0):
        super().__init__()
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure fp16 and CUDA
        if x.dtype != torch.float16:
            x = x.to(dtype=torch.float16)
        if not x.is_cuda:
            x = x.cuda()
        return ext.avg_pool1d_fp16(x,
                                   self.kernel_size,
                                   self.stride,
                                   self.padding)

# ----------------------------------------------------------------------
# Example usage (mirrors reference script)
# ----------------------------------------------------------------------
if __name__ == "__main__":
    batch_size = 64
    in_channels = 128
    input_length = 65536
    kernel_size = 8
    stride = 1
    padding = 4

    model = ModelNew(kernel_size=kernel_size,
                     stride=stride,
                     padding=padding).cuda().half()

    x = torch.rand(batch_size, in_channels, input_length,
                   device='cuda', dtype=torch.float16)
    y = model(x)
    print(y.shape)   # should be (64, 128, 65536) with the same parameters as nn.AvgPool1d
